UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>At Acknowledge Education, you’ll study General English in a fun, relaxed and multicultural environment. Quickly pick up basic language skills to help you settle into life in Australia and deal with everyday situations with ease.The General English course focuses on communication skills within a variety of functional and situational contexts and improves your language skills (Reading, Writing, Listening and Speaking) in real life situations such as working, studying, travelling or living in Australia.</p><p><strong>We will support you during your English studies by:</strong></p><p>Offering extra-curricular classes including conversation club and social trips, focusing on speaking skill and cultural/social features of living in Australia</p><p>Providing support sessions with an individual learning plan, focusing on all language skills including Reading, Writing, Listening, Speaking, Grammar, Vocabulary, Pronunciation and Punctuation</p><p>Running academic and language skills development workshops</p><p>Giving you access to online learning materials</p><p>Arranging meetings with academic advisors, student support officers, and program coordinators</p><p>General English is offered at Elementary, Pre-intermediate, Intermediate and Upper-intermediate levels and can serve as the perfect stepping stone to the study of English for Academic Purposes and IELTS courses.</p>',
    course_duration_per_week = 52,

    entry_requirements = '<p>Minimum 18 years old.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/general-english',
    updated_at = NOW()
WHERE cricos_course_code = '080628A';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>Welcome to the kitchen of your dreams, where your future career is waiting to unfold.</p><p>The Certificate III in Commercial Cookery reflects the role of cooks who use a wide range of well-developed culinary skills and sound knowledge of kitchen operations to prepare menu items. Using discretion and judgement, they work with some independence and under limited supervision, using plans, policies and procedures to guide their work.</p>',
    course_duration_per_week = 52,
    onshore_tuition_fee = 9500,
    enrolment_fee = 200,
    materials_fee = NULL,
    entry_requirements = '<p><b>Domestic</b></p><p>Full tuition fee: $9,500</p><p>Material fee (uniform, knife set, and materials): 600</p><p>Enrolment fee: $200</p><p><b>International</b></p><ul><li><p>IELTS 5.5 or equivalent</p></li><li><p>18 years or older</p></li><li><p>Completion of Year 11 studies or equivalent</p></li><li><p>Please see <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p></li></ul>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/certificate-iii-in-commercial-cookery',
    updated_at = NOW()
WHERE cricos_course_code = '109767C';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>If you’re a born leader, you’ll want to be front-of-house in your career, and the Diploma of Hospitality Management teaches you how to take charge in the fast-paced and exciting world of hospitality. You’ll acquire a broad range of hospitality skills, including providing food and beverage advice and table service, combined with managerial skills such as managing staff performance and preparing and monitoring budgets. You’ll gain a sound knowledge of the industry in order to coordinate hospitality operations and take on the role of a highly skilled senior employee capable of making operational business decisions.</p><p>This qualification provides a pathway to work in any hospitality industry sector as a departmental or business manager. The range of employers includes cafes, catering companies, clubs, hotels, motels, pubs and restaurants, among others. This qualification allows for multiskilling and for specialisation in accommodation services, cookery, food and beverage, and gaming.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 13400,
    onshore_tuition_fee = 13400,
    enrolment_fee = NULL,
    materials_fee = 700,
    entry_requirements = '<h5><b>Academic Requirements</b></h5><p>Entry by interview</p><h5><b>RECOGNITION OF PRIOR LEARNING</b></h5><p>You may be able to shorten your chosen course by factoring in skills acquired through work, life experiences or qualifications obtained from prior formal studies or training. Acknowledge Education recognises AQF qualifications and statements of attainment issued by other registered training organisations.</p><p>Please see <a href="http://www.frontcookingschool.vic.edu.au/wp-content/uploads/sites/4/2019/02/POLICY-AND-PROCEDURE-VET-Recognition-of-Prior-Learning-and-Credit-Transfer-180605-Copy.pdf">Recognition of Prior Learning and Credit Transfer</a> for more information.</p><p><br/></p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/diploma-of-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '110764G';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>The Victorian Certificate of Education (VCE) is Victoria’s senior secondary qualification and a powerful pathway to your future. Recognised nationally and internationally, the VCE opens doors to university study, vocational education and training (VET), and direct entry into the workforce.</p><p>At Acknowledge Education, we offer more than just a qualification — we provide a supportive, student-centred learning experience designed to help you achieve your best. Our dedicated teachers work closely with students, creating an environment where questions are encouraged, confidence is built, and academic success is supported every step of the way.</p><p><strong>When you study VCE with us, you benefit from:</strong></p><p>Experienced and supportive teachers</p><p>Personalised academic guidance</p><p>Close-knit, inclusive learning community</p><p>Focus on your goals and future pathways</p><p>Whether your ambition is university, further training, or employment, the VCE at Acknowledge Education equips you with the knowledge, skills, and confidence to move forward with clarity and success.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 19000,
    onshore_tuition_fee = 19000,
    enrolment_fee = 200,
    materials_fee = NULL,
    entry_requirements = '<h5><b>Domestic</b></h5><p><b>Year 11</b></p><p>• Completion of year 10<br/>• IELTS 5.5 or equivalent*<br/>• <!-- -->If you need to improve your English, you can complete our <a href="https://www.acknowledgeeducation.edu.au/courses/english-for-secondary-schools"><b>English for Secondary Schools</b></a> program before starting Year 11. This course supports your transition into VCE by building essential language and study skills. <!-- -->`</p><p><b>Year 12</b></p><p>• Completion of year 11</p><h5><b>International</b></h5><p><b>Year 11</b></p><p>• Completion of year 10<br/>• IELTS 5.5 or equivalent*<br/>• <!-- -->If you need to improve your English, you can complete our <a href="https://www.acknowledgeeducation.edu.au/courses/english-for-secondary-schools"><b>English for Secondary Schools</b></a> program before starting Year 11. This course supports your transition into VCE by building essential language and study skills. <!-- -->`</p><p><b>Year 12</b></p><p>• Completion of year 11<br/>• IELTS 5.5 or equivalent</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/vce-year-11-12',
    updated_at = NOW()
WHERE cricos_course_code = '032533F';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>The Bachelor of Tourism and Hospitality Management course is a fully accredited Australian higher education degree. The course aims to prepare you to be a competent, knowledgeable and professional candidate for a generalist, entry-level management position in either the tourism or hospitality industry. The Bachelor of Tourism and Hospitality Management course is designed with a strong emphasis on ‘client focus’ and adherence to principles of ethics and sustainability in the industry as part of their professional practice. The course also aims to create an industry professional who is versatile and adaptable with a diverse skill base and ability to adapt to an ever-changing business environment in an increasing global marketplace.</p>',
    course_duration_per_week = 936,
    offshore_tuition_fee = 54000,
    onshore_tuition_fee = 2025,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<p>1. <b><i>Applicants with recent secondary education (within the last three years)</i></b></p><p>If you have recently completed your secondary education and meet the following criteria, you can apply for entry to this course.</p><p><b>Admission Criteria</b></p><p>Evidence of successful completion of a Senior Secondary Certificate of Education to Year 12 or equivalent,* including Units 3 and 4: a study score of at least 25 in English (EAL) or 20 in any other English and an ATAR range from ‘no published ATAR’ to 60.</p><p>*This includes all Commonwealth, State and Territory final year secondary school certificates of education as well as an International Baccalaureate (IB).</p><p><b>Special admission course</b></p><p>Our special admission course covers a range of access and equity schemes that allow you if you are from participating schools or disadvantaged social, economic or cultural environments to receive additional consideration.</p><p><b>Special entry requirements</b></p><p>Demonstrated ability to undertake study at the required level.</p><p>Broadly relevant work experience (documented, e.g., CV), demonstrating a reasonable prospect of success; OR formal, informal, or partially completed, demonstrating a reasonable prospect of success; OR Written submission to demonstrate reasonable prospect of success.</p><p>2. <b><i>Applicants with Vocational Education and Training (VET/TAFE) Study</i></b></p><p>If you have completed previous VET study and meet the following criteria, you can apply for entry to this course.</p><p><b>Admission Criteria</b></p><p>Full or partial completion of an Australian Advanced Diploma or Diploma (or equivalent) in any discipline.</p><p>OR</p><p>Full completion of a Certificate IV in a related discipline.</p><p><b>Special admission course</b></p><p>Our special admission course covers a range of access and equity schemes that allow you—if you are from participating schools or disadvantaged social, economic, or cultural environments—to receive additional consideration.</p><p>3. <b><i>Applicants with Higher Education Study</i></b></p><p>If your highest level of study since leaving secondary education is a higher education course and meets the following criteria, you can apply for entry to this course.</p><p><b>Admission Criteria</b></p><p>Full or partial completion of an Australian Higher Education award (or equivalent). OR</p><p>Completion of two units of Higher Education studies. OR</p><p>Completion of a bridging or enabling course, such as a foundation course or equivalent.</p><p><b>Special admission course</b></p><p>Our special admission course covers a range of access and equity schemes that allow you—if you are from participating schools or disadvantaged social, economic, or cultural environments—to receive additional consideration.</p><p>4. <b><i>Applicants with Work and Life Experience</i></b></p><p>If you have left secondary school more than three years ago and have not undertaken VET or higher education study since then can also apply for entry based on other evidence of academic capability judged to be equivalent, such as relevant work or life experience.</p><p><b>Admission criteria</b></p><p>Five years (minimum) work/life experience in Human Services or similar. OR</p><p>You have completed an Australian Senior Secondary Certificate more than two years ago. PLUS</p><p>Units 3 and 4: a study score of at least 25 in English (EAL) or 20 in any other English (or equivalent).</p><p><b>Special admission course</b></p><p>Our special admission course covers a range of access and equity schemes that allow you—if you are from participating schools or disadvantaged social, economic, or cultural environments—to receive additional consideration.</p><h5><b>Applying for Credit Transfer</b></h5><p>If you have completed relevant prior tertiary studies, you may be eligible for some credit exemptions. This is further outlined in the <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">POLICY HE – Awarding of Credit.</a></p><p><b>Special Admission</b></p><p>Applicants who fall under the following categories will be encouraged to discuss their admission and course options with the admissions team prior to applying. Each application will be assessed on merit, and the applicant’s capacity to successfully complete the course will be carefully considered in this assessment. The categories include recognition as an Indigenous Australian, applicants whose school or home location is in rural or isolated areas, applicants with non-English-speaking background, applicants with difficult living circumstances that have affected their preparation for post-secondary study, applicants with disadvantaged financial background, and applicants with a disability or medical condition affecting their education.</p><p>(see policy<b> – </b><a href="/download/policy-and-procedure-he-–-international-student-admission-201009-1.pdf/file">Higher Education International Student Admission</a>).</p><p><b>Applying for Credit Transfer</b></p><p>If you have completed prior tertiary studies, you may be eligible for some credit exemptions. For further information, please refer to our<a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">Awarding of Credit Policy.</a></p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/bachelor-of-tourism-and-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '103455A';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>Strong frontline leaders are in hot demand in hospitality across the globe. The Advanced Diploma of Hospitality Management will cultivate your passion for this vibrant industry and help you rise through the ranks to take your place as a Senior Manager. You’ll develop a thorough spectrum of skills across the areas of business planning, financial management, human resources, leadership and marketing, to enable you to successfully operate across a broad range of sectors which may include bars, gaming venues, resorts, restaurants or other busy hospitality environments.</p>',
    course_duration_per_week = 130,

    entry_requirements = '<p><b>Domestic</b></p><p>Entry by interview.</p><p><b>International</b></p><ul><li><p>18 years or older</p></li><li><p>Completion of Year 11 studies or equivalent</p></li><li><p>IELTS 5.5 or equivalent</p></li><li><p>Please see <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">International Student Admissions (HE and VET) Policy</a> for further information.</p></li></ul><h5>Recognition of Prior Learning</h5><p>You may be able to shorten your chosen course by factoring in skills acquired through work, life experience or qualifications obtained from prior formal studies or training. Acknowledge Education recognises AQF qualifications and statements of attainment issued by other registered training organisations.</p><p>Please see our <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">VET Recoginition of Prior Learning and Credit Transfer Policy</a> for more information.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/advanced-diploma-of-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '110765F';
