    entry_requirements = '<p><b>Domestic</b></p><ul><li><p><b>Pre-requisite: </b>Diploma of Civil Construction Design (RII50520)</p></li><li><p>Entry by interview</p></li></ul><p><b>International</b></p><p>Pre-requisite: Diploma of Civil Construction Design (RII50520) </p><ul><li><p>IELTS 5.5 or equivalent</p></li><li><p>18 years or older</p></li><li><p>Completion of Year 12 studies or equivalent</p></li></ul><p>Please see <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p>',
