WHERE cricos_course_code = '109630J';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>Counselling has developed substantially over the past decade. It is increasingly being recognised for its efficacy in practice, and for its more practical educational and therapeutic approach. This has positioned counselling as a more attractive career option than its more science- and statistics-based mental health peers.</p><p>Combined with our industry-leading support services and teaching methods, AE fully supports you in your study of advanced counselling topics to develop your skills as a counselling professional.</p><p><b>The Master of Counselling is</b> <b>designed and developed by Australian Institute of Professional Counsellors (AIPC); Higher Education Provider Number: PRV12083, CRICOS Provider Code: 04095M. The course is being delivered through third party arrangements between Acknowledge Education(AE) and Australian Institute of Professional Counsellors (AIPC). AE delivers the course on behalf of AIPC.</b></p><p>The Master of Counselling teaches contemporary counselling topics and skills to an advanced level and is ideally suited to counsellors wanting to develop their knowledge and skills to a higher level, or professionals aspiring to pursue a career in this high-demand industry.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 43260,
    onshore_tuition_fee = 3090,
    enrolment_fee = 200,
    materials_fee = NULL,
    entry_requirements = '<p>Please click<a href="https://www.aipc.net.au/courses/master-of-counselling"> here</a> to view details.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/master-of-counselling',
    updated_at = NOW()
WHERE cricos_course_code = '112554A';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>This qualification equips you, as a pastry chef, to take a supervisory or team-leading role in the kitchen. You will operate independently or with limited guidance from others and use discretion to solve non-routine problems.</p><p>This qualification provides a pathway to work in various organisations where patisserie products are prepared and served, including patisseries, restaurants, hotels, catering operations, clubs, pubs, cafés, and coffee shops.</p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = 15000,
    onshore_tuition_fee = 15000,
    enrolment_fee = 200,
    materials_fee = NULL,
    entry_requirements = '<p><b>Domestic</b></p><p>Entry by interview</p><p><b>International</b></p><ul><li><p>IELTS 5.5 or equivalent</p></li><li><p>18 years or older</p></li><li><p>Completion of Year 12 studies or equivalent</p></li><li><p>Please see <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p></li></ul><p><b>Recognition of Prior Learning</b></p><p>You may be able to shorten your chosen course by factoring in skills acquired through work, life experiences or qualifications obtained from prior formal studies or training. Acknowledge Education recognises AQF qualifications and statements of attainment issued by other registered training organisations.</p><p>Please see <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">Recognition of Prior Learning and Credit Transfer</a> for more information.</p><p><br/></p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/certificate-iv-in-patisserie',
    updated_at = NOW()
