UPDATE courses SET
    course_description = '<h4>Course Overview</h4><p>The Bachelor of Community Services is a fully accredited Australian higher education degree. The course is designed to prepare you for ethical, competent, and culturally relevant community service generalist practice and to equip you with the skills you need for life-long learning and professional development. You will work at the interface between people and their environments, focusing on the experiences of individuals, families, groups and communities. Areas of service provision include child welfare, hospice and palliative care, and juvenile justice and corrections and advocacy.</p><p>You will learn about the theory and values base of human services practice, as well as the knowledge and skills required to work as a professional at a managerial level in the community services sector. You will have the foundational knowledge and skills in community services management you need to continue to a relevant post-graduate higher education program at a university or private education provider.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = 61200,
    onshore_tuition_fee = 2550,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<b>Academic Requirements</b><b>1. Applicants with recent secondary education (within the last 3 years)</b><p>Applicants who have recently completed their secondary education and meet the following criteria can apply for entry to this program.</p><p><b><i>Admission Criteria</i></b></p><p>Evidence of successful completion of a Senior Secondary Certificate of Education to Year 12 or equivalent,* including Units 3 and 4: a study score of at least 25 in English (EAL) or 20 in any other English and an ATAR of 68.</p><p>*This includes all Commonwealth, State and Territory final year secondary school certificates of education as well as an International Baccalaureate (IB).</p><p>Students who have completed their secondary education overseas, where that education was equivalent to an Australian Senior Secondary Certificate of Education, will be assessed for their suitability for the program on a case-by-case basis.</p><h5><b>Special admission program*</b></h5><p>Our special admission program covers a range of access and equity schemes that allow applicants from participating schools or disadvantaged social, economic or cultural environments to receive additional consideration.</p><p><b><i>2. Applicants with Vocational Education and Training (VET/TAFE) Study</i></b></p><p>Applicants with previous VET study who meet the following criteria can apply for entry to this program.</p><p><b><i>Admission Criteria</i></b></p><p>Full or partial completion of an Australian Advanced Diploma or Diploma (or equivalent) in any discipline.</p><p><strong>OR:</strong></p><p>Full completion of a Certificate IV in a related discipline.</p><h5><b>Special admission program*</b></h5><p>Our special admission program covers a range of access and equity schemes that allow applicants from participating schools or disadvantaged social, economic or cultural environments to receive additional consideration.</p><h5><b>Applying for Credit Transfer</b></h5><p>If you have completed prior tertiary studies, you may be eligible for some credit exemptions. For further information, please refer to our <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">Awarding of Credit Policy</a>.</p><p><b><i>3. Applicants with Higher Education Study</i></b></p><p>Applicants whose highest level of study since leaving secondary education is a higher education course and who meet the following criteria can apply for entry into this program.</p><h5><b>Admission Criteria</b></h5><p>Full or partial completion of an Australian Higher Education award (or equivalent).</p><p><strong>OR:</strong></p><p>Completion of two units of Higher Education studies.</p><p><strong>OR:</strong></p><p>Completion of a bridging or enabling course, for example, Foundation course or equivalent.</p><h5><b>Special admission program*</b></h5><p>Our special admission program covers a range of access and equity schemes that allow applicants from participating schools or disadvantaged social, economic or cultural environments to receive additional consideration.</p><h5><b>Applying for Credit Transfer</b></h5><p>If you have completed prior tertiary studies, you may be eligible for some credit exemptions. For further information, please refer to our <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">Awarding of Credit Policy</a>.</p><p><b><i>4. Applicants with Work and Life Experience</i></b></p><p>Applicants who have left secondary school more than three years ago and who have not undertaken VET or higher education study since then can also apply for entry based on other evidence of academic capability judged to be equivalent, such as relevant work or life experience.</p><h5><b>Admission criteria</b></h5><p>Five years (minimum) work/life experience in Community Services or similar.</p><p><strong>OR:</strong></p><p>Applicants who completed an Australian Senior Secondary Certificate more than two years ago.</p><p><strong>PLUS:</strong></p><p>Units 3 and 4: a study score of at least 25 in English (EAL) or 20 in any other English (or equivalent).</p><h5><b>Special admission program*</b></h5><p>Our special admission program covers a range of access and equity schemes that allow applicants from participating schools or disadvantaged social, economic or cultural environments to receive additional consideration.</p><h5><b>Applying for Credit Transfer</b></h5><p>If you have completed prior tertiary studies, you may be eligible for some credit exemptions. For further information, please refer to our <a href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx">Awarding of Credit Policy</a>.</p><p><b><i>*Special Admission</i></b></p><p>Applicants who fall under the following categories can discuss their admission and course options with the admission team prior to applying. Each application will be assessed on its merits, and the applicant’s capacity to successfully complete the course will be carefully considered. The categories are:</p><ul><li><p>applicants recognised as Indigenous Australians,</p></li><li><p>applicants whose school or home location is in rural or isolated areas,</p></li><li><p>applicants with non-English speaking background,</p></li><li><p>applicants with difficult living circumstances that have impacted their preparation for post-secondary study,</p></li><li><p>applicants with disadvantaged financial background, and</p></li><li><p>applicants with disability or medical condition affecting their education.</p></li></ul><b>Additional Requirements</b><p>Other requirements prior to commencing fieldwork placements:</p><ul><li><p>National Police Record Check and/or Police clearance from country of residence</p></li><li><p>Working with Children Check</p></li></ul>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/bachelor-of-community-services',
    updated_at = NOW()
WHERE cricos_course_code = '096281C';
